/* Strata theme: Harbor — generated by @strata/theme-engine 0.1.0. Do not edit by hand. */

:root, [data-strata-theme="harbor"], [data-strata-scheme]:not([data-strata-theme]) {
  color-scheme: light;

  /* Space */
  --strata-space-0: 0px;
  --strata-space-1: 4px;
  --strata-space-2: 8px;
  --strata-space-3: 12px;
  --strata-space-4: 16px;
  --strata-space-5: 20px;
  --strata-space-6: 24px;
  --strata-space-8: 32px;
  --strata-space-10: 40px;
  --strata-space-12: 48px;
  --strata-space-16: 64px;

  /* Radius */
  --strata-radius-button: 8px;
  --strata-radius-field: 8px;
  --strata-radius-container: 12px;
  --strata-radius-badge: 6px;
  --strata-radius-pill: 9999px;

  /* Typography */
  --strata-font-heading: "Source Serif 4", Georgia, Cambria, "Times New Roman", Times, serif;
  --strata-font-body: "Source Sans 3", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --strata-font-mono: "Source Code Pro", ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --strata-font-heading-tracking: 0;
  --strata-font-size-xs: 12px;
  --strata-font-size-sm: 13px;
  --strata-font-size-md: 14px;
  --strata-font-size-lg: 16px;
  --strata-font-size-xl: 20px;
  --strata-font-size-2xl: 24px;
  --strata-font-size-3xl: 32px;
  --strata-line-height-tight: 1.2;
  --strata-line-height-snug: 1.35;
  --strata-line-height-normal: 1.5;
  --strata-font-weight-regular: 400;
  --strata-font-weight-medium: 500;
  --strata-font-weight-semibold: 600;
  --strata-font-weight-bold: 700;

  /* Motion */
  --strata-motion-duration-fast: 120ms;
  --strata-motion-duration-normal: 200ms;
  --strata-motion-easing: cubic-bezier(0.2, 0, 0, 1);

  /* Colour — light */
  --strata-color-surface-canvas: #faf7f3;
  --strata-color-surface-default: #fffdfb;
  --strata-color-surface-raised: #fffdfb;
  --strata-color-surface-sunken: #f3efeb;
  --strata-color-surface-selected: #dff4f0;
  --strata-color-surface-inverse: #221f1a;
  --strata-color-text-default: #221f1a;
  --strata-color-text-subtle: #5e5a55;
  --strata-color-text-disabled: #b5b0aa;
  --strata-color-text-inverse: #fffdfb;
  --strata-color-text-brand: #286a62;
  --strata-color-border-subtle: #e3dfda;
  --strata-color-border-default: #cdc8c2;
  --strata-color-border-strong: #8a8580;
  --strata-color-action-primary-bg: #1d6b63;
  --strata-color-action-primary-fg: #ffffff;
  --strata-color-action-primary-hover: #0a5f58;
  --strata-color-action-primary-pressed: #00544d;
  --strata-color-action-primary-border: #1d6b63;
  --strata-color-action-secondary-bg: #dff4f0;
  --strata-color-action-secondary-fg: #0d3531;
